"""One explicit business choice; technical provenance remains generated by Product."""

from uuid import uuid4

import pytest
from pydantic import ValidationError

from app.features.product.api.deadline_choice import ProductDeadlineChoiceRequest
from app.features.product.api.deadline_listing_terms import OriginalListingTermsRequest


def choice_body():
    return {
        "listing_id": str(uuid4()),
        "expected_revision_number": 0,
        "expected_terms_id": str(uuid4()),
        "expected_listing_version": 1,
        "expected_venue_version": 1,
    }


@pytest.mark.parametrize(
    "field", ["request_id", "fingerprint", "contract_verified", "verified", "known_at"]
)
def test_exit_choice_does_not_accept_caller_trust_or_provenance(field):
    with pytest.raises(ValidationError):
        ProductDeadlineChoiceRequest.model_validate({**choice_body(), field: "user supplied"})


def test_withdrawal_is_explicit_and_never_derived_from_an_empty_read():
    request = ProductDeadlineChoiceRequest.model_validate(
        {
            **choice_body(),
            "listing_id": None,
            "expected_listing_version": None,
            "expected_venue_version": None,
        }
    )
    assert request.listing_id is None
    assert request.expected_revision_number == 0


@pytest.mark.parametrize(
    "field", ["request_id", "document_sha256", "last_trading_on", "source_reference", "verified"]
)
def test_original_import_accepts_file_bytes_not_user_asserted_product_dates(field):
    with pytest.raises(ValidationError):
        OriginalListingTermsRequest.model_validate(
            {"document_base64": "aHRtbA==", field: "asserted"}
        )
